import axios from 'axios';

const isDev = process.env.NODE_ENV === 'development';
const rawBase = process.env.REACT_APP_API_URL;
let baseURL;
if (isDev) {
  // In development, prefer using CRA proxy if REACT_APP_API_URL is missing.
  baseURL = rawBase ? String(rawBase).replace(/^['"]+|['"]+$/g, '') : '';
} else {
  baseURL = String(rawBase || 'http://localhost:4000').replace(/^['"]+|['"]+$/g, '');
}

// Debug: show the computed baseURL in development so we can troubleshoot mismatches
if (process.env.NODE_ENV === 'development') {
  // eslint-disable-next-line no-console
  console.log('API baseURL configured to:', baseURL);
}

import { mockData } from './mockData';

const api = axios.create({ baseURL });

if (process.env.REACT_APP_DEMO_MODE === 'true') {
  // eslint-disable-next-line no-console
  console.log('🚀 MODO DEMO ACTIVADO: Interceptando API con Mock Data estático');

  const originalGet = api.get;
  api.get = function (url, config) {
    // eslint-disable-next-line no-console
    console.log(`[MOCK GET] ${url}`);
    if (url.includes('/auth/me')) return Promise.resolve({ data: mockData.auth.user });
    if (url.includes('/restaurants')) return Promise.resolve({ data: mockData.restaurants });
    if (url.includes('/perspectives')) return Promise.resolve({ data: mockData.perspectives });
    if (url.includes('/dashboard/global')) {
      // Return all KPIs with their entries for global aggregation
      return Promise.resolve({
        data: mockData.kpis.map(k => ({
          kpi: k,
          entries: mockData.allDashboards.find(d => d.kpi.id === k.id)?.entries || []
        }))
      });
    }
    if (url.includes('/dashboard/restaurant/')) {
      const parts = url.split('/');
      const rId = parseInt(parts[parts.length - 1]);
      // Return only KPIs for this specific restaurant
      const filtered = mockData.kpis
        .filter(k => k.restaurant_id === rId)
        .map(k => ({
          kpi: k,
          entries: mockData.allDashboards.find(d => d.kpi.id === k.id)?.entries || []
        }));
      return Promise.resolve({ data: filtered });
    }
    if (url.includes('/alerts')) return Promise.resolve({ data: mockData.alerts });
    if (url.includes('/tasks')) return Promise.resolve({ data: mockData.tasks });
    if (url.includes('/kpis')) return Promise.resolve({ data: mockData.kpis });
    if (url.includes('/objectives')) return Promise.resolve({ data: mockData.objectives });
    return Promise.resolve({ data: {} });
  };

  const originalPost = api.post;
  api.post = function (url, data, config) {
    // eslint-disable-next-line no-console
    console.log(`[MOCK POST] ${url}`, data);
    if (url.includes('/auth/login')) return Promise.resolve({ data: { token: mockData.auth.token } });
    if (url.includes('/ai/insights')) return Promise.resolve({ data: mockData.aiInsight });
    if (url.includes('/tasks')) {
      const newTask = { id: Date.now(), ...data, status: 'pending', created_at: new Date().toISOString(), Kpi: { name: 'KPI Seleccionado' } };
      mockData.tasks.push(newTask);
      return Promise.resolve({ data: newTask });
    }
    return Promise.resolve({ data: {} });
  };

  const originalPut = api.put;
  api.put = function (url, data, config) {
    if (url.includes('/tasks/')) {
      const id = parseInt(url.split('/').pop());
      const t = mockData.tasks.find(x => x.id === id);
      if (t) Object.assign(t, data);
      return Promise.resolve({ data: t || {} });
    }
    return Promise.resolve({ data: {} });
  };
}

api.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// Intercept 401 responses to handle expired/invalid token globally
api.interceptors.response.use(
  (response) => response,
  (error) => {
    const status = error?.response?.status;
    const message = error?.response?.data?.message || '';
    if (status === 401 && (message.toLowerCase().includes('expired') || message.toLowerCase().includes('invalid') || message.toLowerCase().includes('authentication'))) {
      // Clear auth and redirect to login
      localStorage.removeItem('token');
      // eslint-disable-next-line no-console
      console.warn('Session expired or invalid. Redirecting to login.');
      try { window.location.href = '/login'; } catch (e) { /* ignore in non-browser env */ }
    }
    return Promise.reject(error);
  }
);

export default api;
