const generateHistory = (baseValue, variance = 0.1) => {
    const history = [];
    const start = new Date('2025-03-01');
    for (let i = 0; i < 12; i++) {
        const d = new Date(start);
        d.setMonth(d.getMonth() + i);
        const val = baseValue * (1 + (Math.random() * variance * 2 - variance));
        history.push({ period_start: d.toISOString().split('T')[0], value: val.toFixed(2) });
    }
    return history;
};

